steps.content:
Express 用 <code>app.get() / app.post() / app.put() / app.delete()</code> 定义路由：<pre><code>app.get('/api/users', (req, res) => {
  res.json(users);
});
app.post('/api/users', (req, res) => {
  // 创建用户
});</code></pre><p><b>路由参数</b>：<code>/api/users/:id</code> → <code>req.params.id</code></p><p><b>查询参数</b>：<code>/api/users?limit=10</code> → <code>req.query.limit</code></p>

code.js:
const express = require('express');
const app = express();
app.use(express.json());

let users = [
  { id: 1, name: '张三', age: 25 },
  { id: 2, name: '李四', age: 30 }
];
let nextId = 3;

app.get('/api/users', (req, res) => res.json(users));

app.get('/api/users/:id', (req, res) => {
  const user = users.find(u => u.id === +req.params.id);
  user ? res.json(user) : res.status(404).json({ error: '用户不存在' });
});

app.post('/api/users', (req, res) => {
  const user = { id: nextId++, ...req.body };
  users.push(user);
  res.status(201).json(user);
});

app.delete('/api/users/:id', (req, res) => {
  users = users.filter(u => u.id !== +req.params.id);
  res.json({ message: '已删除' });
});

app.listen(3000, () => console.log('API running on :3000'));

steps.content:
中间件是一个函数，每个请求都会经过它：<pre><code>app.use((req, res, next) => {
  console.log(`${req.method} ${req.url}`);
  next(); // 传给下一个中间件
});</code></pre><p><b>常用内置中间件</b>：</p><ul><li><code>express.json()</code> — 解析 JSON 请求体</li><li><code>express.static('public')</code> — 托管静态文件</li><li><code>express.urlencoded()</code> — 解析表单数据</li></ul><p><b>中间件执行顺序</b>：按 <code>app.use()</code> 的注册顺序执行，<code>next()</code> 传递控制权。</p>

code.js:
const express = require('express');
const app = express();
app.use(express.json());

// 自定义日志中间件
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const ms = Date.now() - start;
    console.log(`${req.method} ${req.url} ${res.statusCode} ${ms}ms`);
  });
  next();
});

// 模拟认证中间件
app.use('/api', (req, res, next) => {
  const token = req.headers['authorization'];
  if (!token && req.method !== 'GET') {
    return res.status(401).json({ error: '需要登录' });
  }
  next();
});

app.get('/api/hello', (req, res) => res.json({ msg: '你好' }));

// 错误处理中间件
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: '服务器错误' });
});

app.listen(3000, () => console.log('Server on :3000'));

const express = require('express');
const app = express();
app.use(express.json());

// 日志中间件
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.url}`);
  next();
});

let todos = [
  { id: 1, title: '学习 Node.js', done: true },
  { id: 2, title: '学习 Express', done: false }
];
let nextId = 3;

// 获取所有
app.get('/api/todos', (req, res) => {
  const { done } = req.query;
  if (done !== undefined) {
    return res.json(todos.filter(t => String(t.done) === done));
  }
  res.json(todos);
});

// 创建
app.post('/api/todos', (req, res) => {
  const { title } = req.body;
  if (!title) return res.status(400).json({ error: 'title 必填' });
  const todo = { id: nextId++, title, done: false };
  todos.push(todo);
  res.status(201).json(todo);
});

// 更新
app.put('/api/todos/:id', (req, res) => {
  const todo = todos.find(t => t.id === +req.params.id);
  if (!todo) return res.status(404).json({ error: '不存在' });
  Object.assign(todo, req.body);
  res.json(todo);
});

// 删除
app.delete('/api/todos/:id', (req, res) => {
  todos = todos.filter(t => t.id !== +req.params.id);
  res.json({ message: '已删除' });
});

app.listen(3000, () => console.log('TODO API on :3000'));

steps.content:
把路由拆到独立文件，不再全部堆在 server.js：<pre><code>// routes/users.js
const router = require('express').Router();
router.get('/', (req, res) => { ... });
router.post('/', (req, res) => { ... });
module.exports = router;

// server.js
const userRoutes = require('./routes/users');
app.use('/api/users', userRoutes);</code></pre><p><b>好处</b>：代码清晰、团队协作、每个模块独立维护。</p>

code.js:
// 模拟模块化路由结构
const express = require('express');
const app = express();
app.use(express.json());

// users 路由模块
const userRouter = express.Router();
userRouter.get('/', (req, res) => {
  res.json([{ id: 1, name: '张三' }, { id: 2, name: '李四' }]);
});
userRouter.get('/:id', (req, res) => {
  res.json({ id: +req.params.id, name: '用户' + req.params.id });
});
userRouter.post('/', (req, res) => {
  res.status(201).json({ id: 3, ...req.body });
});

// posts 路由模块
const postRouter = express.Router();
postRouter.get('/', (req, res) => {
  res.json([{ id: 1, title: '第一篇' }, { id: 2, title: '第二篇' }]);
});

app.use('/api/users', userRouter);
app.use('/api/posts', postRouter);

app.listen(3000, () => console.log('Modular API on :3000'));

steps.content:
Express 有 4 个参数的中间件专门处理错误：<pre><code>app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({
    error: err.message
  });
});</code></pre><p>在路由中用 <code>next(err)</code> 传递错误给错误处理器。</p>

code.js:
const express = require('express');
const app = express();

class AppError extends Error {
  constructor(message, status = 500) {
    super(message);
    this.status = status;
  }
}

// 模拟成功路由
app.get('/api/ok', (req, res) => {
  res.json({ status: 'ok' });
});

// 模拟业务错误
app.get('/api/error', (req, res, next) => {
  next(new AppError('这是一个测试错误', 400));
});

// 404 处理
app.use((req, res) => {
  res.status(404).json({ error: `路由不存在: ${req.method} ${req.url}` });
});

// 全局错误处理
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${err.message}`);
  res.status(err.status || 500).json({ error: err.message });
});

app.listen(3000, () => console.log('Error handling demo on :3000'));
